<?php
include('../auth/check.php');
include('../config/db.php');

$sql = "SELECT q.id,q.queue_number,q.queue_type,q.workflow_status,q.counter_number,q.table_number,b.first_name,b.middle_name,b.last_name,b.ext_name,b.beneficiary_code,b.age,b.sex,b.barangay,b.lgu,e.form_locked,e.eligibility_status,e.approved_cash_amount FROM queue_entries q JOIN beneficiaries b ON b.id=q.beneficiary_id LEFT JOIN eligibility_forms e ON e.queue_entry_id=q.id WHERE DATE(q.transaction_date)=CURDATE() AND q.workflow_status IN ('WAITING_STEP_2','CALLED_STEP_2','HELD') ORDER BY CASE WHEN q.workflow_status='CALLED_STEP_2' THEN 0 WHEN q.queue_type='priority' THEN 1 ELSE 2 END,q.id ASC";
$result = $conn->query($sql);
function h($v){return htmlspecialchars($v ?? '',ENT_QUOTES,'UTF-8');}
function fullName($r){return trim($r['last_name'].', '.$r['first_name'].' '.$r['middle_name'].' '.$r['ext_name']);}
function counterDropdown($name='counter_number',$selected=1){$selected=intval($selected ?: 1);$html='<select class="counter-select" name="'.$name.'" title="Counter">';for($i=1;$i<=10;$i++){$sel=$i===$selected?' selected':'';$html.='<option value="'.$i.'"'.$sel.'>C'.$i.'</option>';}$html.='</select>';return $html;}
?>
