der-radius:999px;background:#e5e7eb;color:#374151;font-size:10px;font-weight:900;text-transform:uppercase}.badge{display:inline-block;min-width:120px;text-align:center;padding:7px 10px;border-radius:999px;background:#e5e7eb;color:#111827;font-size:11px;font-weight:900}.ok{background:#dcfce7;color:#166534}.warn{background:#fef3c7;color:#92400e}.call-b{background:#dbeafe;color:#1e40af}.counter-chip{display:block;margin-top:5px;color:#0b2e83;font-weight:900;font-size:12px}.actions{display:flex;gap:7px;align-items:center;justify-content:center}.actions form{margin:0;display:inline-flex;gap:7px;align-items:center}.counter-select{height:34px;width:50px;border:1px solid #cbd5e1;border-radius:8px;background:white;font-size:12px;font-weight:900;color:#111827;padding:0 4px}.ib{width:36px;height:36px;border:0;border-radius:8px;color:white;display:inline-flex;align-items:center;justify-content:center;text-decoration:none;cursor:pointer;flex-shrink:0}.ib span{font-size:19px}.call{background:#10b981}.gis{background:#2563eb}.done{background:#16a34a}.cancel{background:#dc2626}.off{opacity:.35;pointer-events:none}.pager{display:flex;align-items:center;justify-content:center;gap:8px;padding:12px;border-top:1px solid #e5e7eb;background:#fff;flex-shrink:0}.pg{height:36px;min-width:36px;border:1px solid #cbd5e1;background:white;border-radius:8px;padding:7px 10px;cursor:pointer;font-weight:900}.pg:disabled{opacity:.35;cursor:not-allowed}.page-info{font-size:14px;color:#475569;font-weight:900}.footer-note{display:flex;justify-content:space-between;padding:10px 14px;border-top:1px solid #e5e7eb;background:#f8fafc;color:#64748b;font-size:13px;flex-shrink:0}@media(max-width:1050px){.toolbar{grid-template-columns:1fr 1fr}.tbl{font-size:12px}.tbl th,.tbl td{padding:10px 6px}.counter-select{width:44px}.ib{width:32px;height:32px}}
