<?php $n=1; if($result): while($r=$result->fetch_assoc()): $isPrio=$r['queue_type']==='priority'; $isHeld=$r['workflow_status']==='HELD'; $isCalled=$r['workflow_status']==='CALLED_STEP_2'; $isWaiting=$r['workflow_status']==='WAITING_STEP_2'; $counter=intval($r['counter_number'] ?: $r['table_number'] ?: 1); $gis=intval($r['form_locked']??0)===1 && ($r['eligibility_status']??'')==='Eligible' && floatval($r['approved_cash_amount']??0)>0; $statusClass=$gis?'ok':($isCalled?'call-b':'warn'); ?>
<tr class="data <?php echo $isHeld?'held':($isPrio?'prio':''); ?>" data-type="<?php echo h($r['queue_type']); ?>" data-status="<?php echo h($r['workflow_status']); ?>"><td><?php echo $n++; ?></td><td class="qno <?php echo $isPrio?'qprio':''; ?>"><?php echo h($r['queue_number']); ?></td><td><span class="client-name"><?php echo h(fullName($r)); ?></span><span class="cat"><?php echo $isPrio?'PRIO':'REGULAR'; ?></span><span class="sub"><?php echo h($r['beneficiary_code'] ?? ''); ?></span></td><td><?php echo h($r['barangay']); ?></td><td><?php echo intval($r['age']); ?></td><td><?php echo h($r['sex']); ?></td><td><?php echo h($r['lgu']); ?></td><td><span class="badge <?php echo $statusClass; ?>"><?php echo $gis?'GIS LOCKED':h($r['workflow_status']); ?></span><?php if($isCalled): ?><span class="counter-chip">Counter <?php echo $counter; ?></span><?php endif; ?></td><td><div class="actions">
<?php if($isWaiting): ?>
<form method="POST" action="../api/call_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><?php echo counterDropdown('counter_number',1); ?><input type="hidden" name="redirect" value="../staff/assessment_screen.php"><button class="ib call" title="Call"><span class="material-icons">campaign</span></button></form>
<form method="POST" action="../api/cancel_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="redirect" value="../staff/assessment_screen.php"><button class="ib cancel" title="Cancel"><span class="material-icons">close</span></button></form>
<?php elseif($isCalled): ?>
<a class="ib gis" href="eligibility_form.php?queue_id=<?php echo intval($r['id']); ?>" title="GIS"><span class="material-icons">description</span></a>
<form method="POST" action="../api/mark_assessed.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="counter_number" value="<?php echo $counter; ?>"><button class="ib done <?php echo !$gis?'off':''; ?>" title="Assessed"><span class="material-icons">check_circle</span></button></form>
<form method="POST" action="../api/cancel_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="redirect" value="../staff/assessment_screen.php"><button class="ib cancel" title="Cancel"><span class="material-icons">close</span></button></form>
<?php else: ?>
<form method="POST" action="../api/cancel_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="redirect" value="../staff/assessment_screen.php"><button class="ib cancel" title="Cancel"><span class="material-icons">close</span></button></form>
<?php endif; ?>
</div></td></tr>
<?php endwhile; endif; ?>
</tbody></table></div><div class="pager" id="p"></div><div class="footer-note"><span id="recordInfo">Showing records...</span><span id="lastUpdated">Last updated: --</span></div></div></section></main><?php include('sidebar.php'); ?></div><script>
const rows=[...document.querySelectorAll('.data')],s=document.getElementById('s'),t=document.getElementById('t'),st=document.getElementById('st'),rpp=document.getElementById('rowsPerPage'),p=document.getElementById('p'),info=document.getElementById('recordInfo'),last=document.getElementById('lastUpdated');let page=1;function filteredRows(){let a=s.value.toLowerCase(),ty=t.value,sta=st.value;return rows.filter(r=>(!ty||r.dataset.type===ty)&&(!sta||r.dataset.status===sta)&&r.innerText.toLowerCase().includes(a))}function apply(){let vis=filteredRows(),per=parseInt(rpp.value,10),pages=Math.max(1,Math.ceil(vis.length/per));if(page>pages)page=pages;rows.forEach(r=>r.style.display='none');vis.slice((page-1)*per,page*per).forEach(r=>r.style.display='');p.innerHTML=`<button class="pg" ${page===1?'disabled':''} onclick="page=1;apply()">«</button><button class="pg" ${page===1?'disabled':''} onclick="page--;apply()">‹</button><span class="page-info">Page ${page} of ${pages}</span><button class="pg" ${page===pages?'disabled':''} onclick="page++;apply()">›</button><button class="pg" ${page===pages?'disabled':''} onclick="page=${pages};apply()">»</button>`;let start=vis.length?(page-1)*per+1:0,end=Math.min(page*per,vis.length);info.textContent=`Showing ${start}-${end} of ${vis.length} filtered records (${rows.length} total)`;last.textContent='Last updated: '+new Date().toLocaleTimeString()}[s,t,st,rpp].forEach(e=>{e.addEventListener('input',()=>{page=1;apply()});e.addEventListener('change',()=>{page=1;apply()})});apply();
</script></body></html>
